// M2 Dynarmic probe. Implementation supplied by ChatGPT on nirally/Vitox-Bridge
// Issue #1 (comment 6224354062); used unchanged.
#include "common.h"

#include <dynarmic/interface/A32/a32.h>
#include <dynarmic/interface/A32/config.h>

#include "vitox_dynarmic_build.h" // generated by dynarmic-build (commit, shims)

#include <array>
#include <atomic>
#include <chrono>
#include <cstdint>
#include <memory>
#include <thread>
#include <vector>

namespace vitox {

using u8  = std::uint8_t;
using u16 = std::uint16_t;
using u32 = std::uint32_t;
using u64 = std::uint64_t;

class ProbeEnv final : public Dynarmic::A32::UserCallbacks {
public:
    u64 ticks_left = 0;
    std::array<u8, 4096> memory{};
    bool fallback = false;
    bool exception = false;

    u8 MemoryRead8(u32 vaddr) override {
        return vaddr < memory.size() ? memory[vaddr] : 0;
    }

    u16 MemoryRead16(u32 vaddr) override {
        return static_cast<u16>(MemoryRead8(vaddr)) |
               static_cast<u16>(static_cast<u16>(MemoryRead8(vaddr + 1)) << 8);
    }

    u32 MemoryRead32(u32 vaddr) override {
        return static_cast<u32>(MemoryRead16(vaddr)) |
               (static_cast<u32>(MemoryRead16(vaddr + 2)) << 16);
    }

    u64 MemoryRead64(u32 vaddr) override {
        return static_cast<u64>(MemoryRead32(vaddr)) |
               (static_cast<u64>(MemoryRead32(vaddr + 4)) << 32);
    }

    void MemoryWrite8(u32 vaddr, u8 value) override {
        if (vaddr < memory.size())
            memory[vaddr] = value;
    }

    void MemoryWrite16(u32 vaddr, u16 value) override {
        MemoryWrite8(vaddr, static_cast<u8>(value));
        MemoryWrite8(vaddr + 1, static_cast<u8>(value >> 8));
    }

    void MemoryWrite32(u32 vaddr, u32 value) override {
        MemoryWrite16(vaddr, static_cast<u16>(value));
        MemoryWrite16(vaddr + 2, static_cast<u16>(value >> 16));
    }

    void MemoryWrite64(u32 vaddr, u64 value) override {
        MemoryWrite32(vaddr, static_cast<u32>(value));
        MemoryWrite32(vaddr + 4, static_cast<u32>(value >> 32));
    }

    void InterpreterFallback(u32, std::size_t) override {
        fallback = true;
        ticks_left = 0;
    }

    void CallSVC(u32) override {
        ticks_left = 0;
    }

    void ExceptionRaised(u32, Dynarmic::A32::Exception) override {
        exception = true;
        ticks_left = 0;
    }

    void AddTicks(u64 ticks) override {
        ticks_left = ticks >= ticks_left ? 0 : ticks_left - ticks;
    }

    u64 GetTicksRemaining() override {
        return ticks_left;
    }
};

static Dynarmic::A32::UserConfig make_config(ProbeEnv& env, std::size_t cache_size = 0) {
    Dynarmic::A32::UserConfig cfg{};
    cfg.callbacks = &env;
    cfg.arch_version = Dynarmic::A32::ArchVersion::v7;
    if (cache_size != 0)
        cfg.code_cache_size = cache_size;
    return cfg;
}

static bool run_arm(Dynarmic::A32::Jit& cpu, ProbeEnv& env) {
    env.memory.fill(0);
    env.fallback = false;
    env.exception = false;

    // ARMv7:
    //   mov r0, #42
    //   b .
    env.MemoryWrite32(0, 0xE3A0002A);
    env.MemoryWrite32(4, 0xEAFFFFFE);

    cpu.Reset();
    cpu.Regs()[15] = 0;
    cpu.SetCpsr(0x00000010); // ARM, user mode
    env.ticks_left = 1;

    cpu.Run();
    return cpu.Regs()[0] == 42 && !env.fallback && !env.exception;
}

static bool run_thumb_shift(Dynarmic::A32::Jit& cpu, ProbeEnv& env, unsigned shift, u32 expected) {
    env.memory.fill(0);
    env.fallback = false;
    env.exception = false;

    const u16 lsl_r0_r1 = static_cast<u16>((shift << 6) | (1u << 3));
    env.MemoryWrite16(0, lsl_r0_r1); // lsls r0, r1, #shift
    env.MemoryWrite16(2, 0xE7FE);    // b .

    cpu.Reset();
    cpu.Regs()[0] = 0;
    cpu.Regs()[1] = 2;
    cpu.Regs()[15] = 0;
    cpu.SetCpsr(0x00000030); // Thumb, user mode
    env.ticks_left = 1;

    cpu.Run();
    return cpu.Regs()[0] == expected && !env.fallback && !env.exception;
}

static bool basic_and_cache_tests(std::size_t cache_size, const char* label) {
    ProbeEnv env;
    auto cfg = make_config(env, cache_size);

    const auto t0 = std::chrono::steady_clock::now();
    Dynarmic::A32::Jit cpu{cfg};
    const auto t1 = std::chrono::steady_clock::now();

    const auto create_us =
        std::chrono::duration_cast<std::chrono::microseconds>(t1 - t0).count();

    log_line(Log::Dynarmic,
             "%s JIT create cache=%zu bytes time_us=%lld",
             label,
             cache_size ? cache_size : static_cast<std::size_t>(128ull * 1024 * 1024),
             static_cast<long long>(create_us));

    const bool arm_ok = run_arm(cpu, env);
    log_line(Log::Dynarmic, "%s ARM result=%s r0=%u",
             label, arm_ok ? "PASS" : "FAIL", cpu.Regs()[0]);

    const bool thumb_ok = run_thumb_shift(cpu, env, 2, 8);
    log_line(Log::Dynarmic, "%s Thumb result=%s r0=%u",
             label, thumb_ok ? "PASS" : "FAIL", cpu.Regs()[0]);

    // Compile shift-by-2, patch guest code to shift-by-1,
    // invalidate only the changed guest range, then rerun.
    env.memory.fill(0);
    env.MemoryWrite16(0, 0x0088); // lsls r0,r1,#2
    env.MemoryWrite16(2, 0xE7FE);
    cpu.Reset();
    cpu.Regs()[1] = 2;
    cpu.Regs()[15] = 0;
    cpu.SetCpsr(0x30);
    env.ticks_left = 1;
    cpu.Run();
    const bool before_ok = cpu.Regs()[0] == 8;

    env.MemoryWrite16(0, 0x0048); // lsls r0,r1,#1
    // Vitox: InvalidateCacheRange()/ClearCache() only post a CacheInvalidation halt that
    // the next Run() services; Reset() (jit_state = {}) clears that halt bit, so the
    // request must be made after Reset(), not before.
    cpu.Reset();
    cpu.Regs()[1] = 2;
    cpu.Regs()[15] = 0;
    cpu.SetCpsr(0x30);
    env.ticks_left = 1;
    cpu.InvalidateCacheRange(0, 2);
    cpu.Run();
    const bool invalidate_ok = cpu.Regs()[0] == 4;

    log_line(Log::Dynarmic,
             "%s invalidate before=%d after=%d value=%u",
             label, before_ok ? 1 : 0, invalidate_ok ? 1 : 0, cpu.Regs()[0]);

    // Re-enter the Thumb block at 0 with r1 = 2. `clear` posts ClearCache after Reset().
    const auto rerun = [&](bool clear) {
        cpu.Reset();
        cpu.Regs()[1] = 2;
        cpu.Regs()[15] = 0;
        cpu.SetCpsr(0x30);
        env.ticks_left = 1;
        if (clear)
            cpu.ClearCache(); // after Reset(), same reason as above
        cpu.Run();
        return cpu.Regs()[0];
    };

    // ClearCache must discard a stale translation: the cached block yields A = 4 (lsls #1);
    // patch the guest to B = 16 (lsls #3) WITHOUT invalidating, confirm the stale A still
    // runs, then ClearCache and expect B. A no-op ClearCache would keep returning A.
    const u32 clear_a = rerun(false);
    env.MemoryWrite16(0, 0x00C8); // lsls r0,r1,#3
    const u32 clear_stale = rerun(false);
    const u32 clear_b = rerun(true);
    const bool clear_ok = clear_a == 4 && clear_stale == 4 && clear_b == 16;

    log_line(Log::Dynarmic, "%s ClearCache result=%s A=%u stale=%u after_clear=%u (want 4/4/16)",
             label, clear_ok ? "PASS" : "FAIL", clear_a, clear_stale, clear_b);

    // Reset must not destroy the translated cache: patch the guest back to lsls #1 without
    // invalidating; after Reset() the cached lsls #3 block must still run (16, not 2*2=4).
    env.MemoryWrite16(0, 0x0048); // lsls r0,r1,#1
    const u32 reset_value = rerun(false);
    const bool reset_ok = reset_value == 16;

    log_line(Log::Dynarmic, "%s Reset result=%s value=%u (want cached 16)",
             label, reset_ok ? "PASS" : "FAIL", reset_value);

    return arm_ok && thumb_ok && before_ok && invalidate_ok && clear_ok && reset_ok;
}

static bool scale_test(std::size_t cache_size, int count, const char* label) {
    mem_snapshot("dyn_before_construct");

    std::vector<std::unique_ptr<ProbeEnv>> envs;
    std::vector<std::unique_ptr<Dynarmic::A32::Jit>> jits;
    envs.reserve(count);
    jits.reserve(count);

    const auto t0 = std::chrono::steady_clock::now();

    for (int i = 0; i < count; ++i) {
        auto env = std::make_unique<ProbeEnv>();
        env->MemoryWrite16(0, 0x0088);
        env->MemoryWrite16(2, 0xE7FE);

        auto cfg = make_config(*env, cache_size);
        auto jit = std::make_unique<Dynarmic::A32::Jit>(cfg);

        jit->Regs()[1] = 2;
        jit->Regs()[15] = 0;
        jit->SetCpsr(0x30);
        env->ticks_left = 1;

        envs.emplace_back(std::move(env));
        jits.emplace_back(std::move(jit));
    }

    const auto t1 = std::chrono::steady_clock::now();
    const auto create_ms =
        std::chrono::duration_cast<std::chrono::milliseconds>(t1 - t0).count();

    log_line(Log::Dynarmic,
             "scale %s count=%d cache_each=%zu create_ms=%lld",
             label, count, cache_size,
             static_cast<long long>(create_ms));

    mem_snapshot("dyn_after_construct");

    std::vector<int> ok(static_cast<std::size_t>(count), 0);
    std::vector<std::thread> threads;
    threads.reserve(count);

    for (int i = 0; i < count; ++i) {
        threads.emplace_back([&, i] {
            jits[i]->Run();
            ok[i] = (jits[i]->Regs()[0] == 8 &&
                     !envs[i]->fallback &&
                     !envs[i]->exception) ? 1 : 0;
        });
    }

    for (auto& t : threads)
        t.join();

    int passed = 0;
    for (int v : ok)
        passed += v;

    log_line(Log::Dynarmic,
             "scale %s count=%d concurrent_pass=%d/%d",
             label, count, passed, count);

    mem_snapshot("dyn_after_run");

    jits.clear();
    envs.clear();
    Sleep(100);

    mem_snapshot("dyn_after_destroy");

    return passed == count;
}

void probe_dynarmic() {
    log_line(Log::Dynarmic, "Dynarmic M2 begin");
    log_line(Log::Dynarmic, "build: dynarmic commit=%s tree=%s no_execute_support=%s shims=%s",
             VITOX_DYNARMIC_COMMIT, VITOX_DYNARMIC_TREE,
             VITOX_DYNARMIC_NO_EXECUTE_SUPPORT ? "ON" : "OFF", VITOX_DYNARMIC_SHIMS);
    mem_snapshot("dyn_begin");

    constexpr std::size_t kDefault = 128ull * 1024 * 1024;
    constexpr std::size_t kReduced = 16ull * 1024 * 1024;

    bool overall = true;

    overall &= basic_and_cache_tests(0, "default");
    overall &= basic_and_cache_tests(kReduced, "reduced16M");

    for (int n : {1, 2, 4, 8}) {
        overall &= scale_test(kDefault, n, "default128M");
    }

    for (int n : {1, 2, 4, 8}) {
        overall &= scale_test(kReduced, n, "reduced16M");
    }

    mem_snapshot("dyn_end");
    set_status(&Status::dyn, overall ? "PASS" : "FAIL");
    log_line(Log::Dynarmic, "Dynarmic M2 %s", overall ? "PASS" : "FAIL");
}

} // namespace vitox
